// P7 east kitchen: a 2 x 2 mirror kitchen (inner air x92..93, z14..15, y3..6). The door is at (93,3..4,13); the
// hearth mouth (92,3,16) is in the back wall, its fire outside. Focal piece: the lit stove at (92,3,15) against the
// hearth wall. Counter: a spruce fence post with a top slab at (93,3..4,15), a flower pot on it. Lanterns hang from
// the ceiling (y7) at (92,6,14) and (93,6,15). Cells (93,3,14) (the doorway's first cell) and (92,3,14) (the lane to
// the stove) stay clear.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { stove } from "../vocab.mjs";

export function build(g) {
  stove(g, 92, 3, 15, "north");
  // y3..y6, rows along z (z14 then z15), columns x92 then x93
  layers(
    g,
    [92, 3, 14],
    {
      F: "spruce_fence",
      T: ["spruce_slab", { type: "top" }],
      P: "flower_pot",
      L: ["lantern", { hanging: "true" }],
    },
    [
      [["..", ".F"]],          // y3: counter post at (93,3,15)
      [["..", ".T"]],          // y4: top slab counter at (93,4,15)
      [["..", ".P"]],          // y5: flower pot on the counter
      [["L.", ".L"]],          // y6: hanging lanterns (92,6,14) and (93,6,15)
    ],
  );
}

