// Test-only: a stand-in shell around the P7 east kitchen so the room check sees walls, floor, ceiling, hearth fire.
import { load, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [inp, out] = process.argv.slice(2);
const g = load(inp);
const isAir = (x, y, z) => { const b = g.get(x, y, z); return !b || b[0] === "air"; };
const put = (x, y, z, ...b) => { if (isAir(x, y, z)) g.set(x, y, z, ...b); };
for (let x = 91; x <= 94; x++) for (let z = 13; z <= 16; z++) put(x, 2, z, "dark_oak_planks");
for (let z = 13; z <= 16; z++) for (let y = 3; y <= 6; y++) { put(91, y, z, "bricks"); put(94, y, z, "bricks"); }
for (let x = 91; x <= 94; x++) for (let y = 3; y <= 6; y++) { if (x > 91 && x < 94) { put(x, y, 13, "bricks"); put(x, y, 16, "bricks"); } }
for (let x = 91; x <= 94; x++) put(x, 7, 13 + 0, "bricks");
for (let x = 91; x <= 94; x++) for (let z = 13; z <= 16; z++) put(x, 7, z, "bricks");
// doorway (93,3..4,13) left as air, window x94 z14 y4..5 as glass
put(94, 4, 14, "glass_pane"); put(94, 5, 14, "glass_pane");
// hearth: mouth (92,3,16) air; fire outside at (92,3,17) on hay
put(92, 2, 17, "hay_block"); g.set(92, 3, 17, "campfire", { lit: "true", signal_fire: "true" });
g.save(out);
console.log("ok");
EOF
